package com.jobsphere.service;
import com.jobsphere.entity.*; import com.jobsphere.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service public class ProfileAiService { private final OllamaService ai; private final DashboardInsightRepository dr; public ProfileAiService(OllamaService a,DashboardInsightRepository d){ai=a;dr=d;} public DashboardInsight analyze(User u,UserProfile p){String snapshot=profile(u,p);String prompt="You are JOBSPHERE's career dashboard advisor. Analyze ONLY the supplied candidate profile. Do not invent qualifications. Return ONLY valid JSON with exactly these keys: headline, summary, strengths (array of strings), focusAreas (array of strings), nextActions (array of strings), suggestedRoles (array of strings), readiness (number 0-100). Keep advice practical and specific to the candidate. PROFILE:\n"+snapshot;String json=ai.generate(prompt);DashboardInsight d=new DashboardInsight();d.userId=u.id;d.profileSnapshot=snapshot;d.insightJson=json;d.createdAt=LocalDateTime.now();return dr.save(d);} public static String profile(User u,UserProfile p){return "Name: "+u.fullName+"\nLocation: "+nz(p.location)+"\nUniversity: "+nz(p.university)+"\nDegree: "+nz(p.degree)+"\nGraduation year: "+nz(p.graduationYear)+"\nEmployment status: "+nz(p.employmentStatus)+"\nHeadline: "+nz(p.headline)+"\nEducation: "+nz(p.education)+"\nTechnical skills: "+nz(p.skills)+"\nSoft skills: "+nz(p.softSkills)+"\nExperience: "+nz(p.experience)+"\nProjects: "+nz(p.projects)+"\nCertifications: "+nz(p.certifications)+"\nCareer interests: "+nz(p.careerInterest)+"\nCareer goal: "+nz(p.careerGoal); } static String nz(Object x){return x==null?"":String.valueOf(x);} }
